diagram.source:
flowchart TD
  A[Need to repeat code?] --> B{Need an index?}
  B -->|Yes| C[for loop]
  B -->|No| D{Walk a collection?}
  D -->|Yes| E[foreach loop]
  D -->|No| F{Run at least once?}
  F -->|Yes| G[do-while loop]
  F -->|No| H[while loop]

snippet.code:
foreach (var row in csvRows)
{
    ImportRow(row);
}

for (int i = 0; i < csvRows.Length; i++)
{
    if (i == 0) continue; // skip header by index
    ImportRow(csvRows[i]);
}

int retries = 0;
while (retries < 3 && !success)
{
    success = TryConnect();
    retries++;
}

// do-while: body runs at least once
int attempt = 0;
do
{
    attempt++;
    result = ProcessOnce();
} while (result == null && attempt < 5);

// OK: modify properties of the item (if mutable)
foreach (var order in orders)
{
    order.Status = "Processed";
}

// NOT OK: add to the same list during foreach
// foreach (var x in list) { list.Add(x); } // throws!

// Safe deletion: iterate backwards with for
for (int i = list.Count - 1; i >= 0; i--)
{
    if (ShouldRemove(list[i])) list.RemoveAt(i);
}
